// 获取第一次掷骰子的人
getFirstRoller() {
    const playerIds = this.getSortedPlayerIds();

    if (this.currentRound === 0) {
        // 周期第一局：座东的玩家坐庄并先掷骰子
        const dongPlayer = Array.from(this.players.values()).find(p => p.seatNum === 1);
        if (dongPlayer) {
            this.gameState.dealerSeat = 1;
            this.gameState.dealer = playerIds.indexOf(dongPlayer.id);
            return dongPlayer.id;
        }

input.new_string:
// 获取第一次掷骰子的人
getFirstRoller() {
    const playerIds = this.getSortedPlayerIds();

    if (this.currentRound === 0) {
        // 周期第一局：座东的玩家坐庄并先掷骰子
        // 座位与方位对应：1号位=南，2号位=东，3号位=西，4号位=北
        const dongPlayer = Array.from(this.players.values()).find(p => p.seatNum === 2);
        if (dongPlayer) {
            this.gameState.dealerSeat = 2;
            this.gameState.dealer = playerIds.indexOf(dongPlayer.id);
            return dongPlayer.id;
        }

