   565→    // 开始发牌
   566→    startDealCards() {
   567→        this.currentRound++;
   568→        this.gameState.roundPhase = 'playing';
   569→        this.roundReadyPlayers.clear();
   570→
   571→        // 重置玩家准备状态（局间准备用）
   572→        for (const player of this.players.values()) {
   573→            player.ready = false;
   574→        }
   575→
   576→        // 重置每局游戏状态
   577→        this.gameState.discardedPile = [];
   578→        this.gameState.showedCards = {};
   579→        this.gameState.faUsed = {};
   580→        this.gameState.lastDrawn = null;
   581→
   582→        // 初始化手牌
   583→        const playerIds = this.getSortedPlayerIds();
   584→        for (const pid of playerIds) {
   585→            this.gameState.hands[pid] = [];
   586→            this.gameState.showedCards[pid] = { fa: [], gang: [] };
   587→            this.gameState.faUsed[pid] = false;
   588→        }
   589→
   590→        // 逆时针顺序：东(1)→北(4)→西(3)→南(2)
   591→        // playerIds 是 [座位1, 座位2, 座位3, 座位4]（顺时针）
   592→        // 逆时针需要调整为 [座位1, 座位4, 座位3, 座位2]
   593→        const counterClockwiseIds = [
   594→            playerIds[0], // 座位1(东)
   595→            playerIds[3], // 座位4(北)
   596→            playerIds[2], // 座位3(西)
   597→            playerIds[1]  // 座位2(南)
   598→        ];
   599→
   600→        // 发牌：每人4张×3轮，然后每人1张，庄家多1张
   601→        // 每人4张×3轮（逆时针顺序）
   602→        for (let round = 0; round < 3; round++) {
   603→            for (const pid of counterClockwiseIds) {
   604→                for (let i = 0; i < 4; i++) {
   605→                    const card = this.gameState.deck.pop();
   606→                    if (card) this.gameState.hands[pid].push(card);
   607→                }
   608→            }
   609→        }
   610→
   611→        // 每人1张（逆时针顺序）
   612→        for (const pid of counterClockwiseIds) {
   613→            const card = this.gameState.deck.pop();
   614→            if (card) this.gameState.hands[pid].push(card);
   615→        }
   616→
   617→        // 庄家多拿1张
   618→        const dealerPid = playerIds[this.gameState.dealer];
   619→        const extraCard = this.gameState.deck.pop();
   620→        if (extraCard) this.gameState.hands[dealerPid].push(extraCard);
   621→
   622→        // 庄家先出牌
   623→        this.gameState.currentPlayer = this.gameState.dealer;
   624→
   625→        // 排序手牌
   626→        for (const pid of playerIds) {
   627→            this.sortHand(pid);
   628→        }
   629→
   630→        console.log(`牌桌${this.tableNumber} 第${this.currentRound}局开始，庄家座位: ${this.gameState.dealerSeat}，万能牌: ${cardName(this.gameState.wildCard)}`);
   631→
   632→        // 先发送发牌动画消息
   633→        this.broadcastDealStart();
   634→
   635→        // 等待发牌动画完成后发送游戏状态
