// 更新牌墙状态
updateWallState() {
    // 计算剩余牌数对应的牌墩
    const totalCards = this.gameState.deck.length;
    const totalPiles = Math.ceil(totalCards / 2);

    // 简化处理：均匀分配到四个方位
    const pilesPerDirection = Math.floor(totalPiles / 4);
    const remainder = totalPiles % 4;

    this.gameState.wallState = {
        1: pilesPerDirection + (remainder > 0 ? 1 : 0),
        2: pilesPerDirection + (remainder > 1 ? 1 : 0),
        3: pilesPerDirection + (remainder > 2 ? 1 : 0),
        4: pilesPerDirection
    };
}

// 出牌
playCard(playerId, cardId) {
    const hand = this.gameState.hands[playerId];
    if (!hand) return false;

    const cardIndex = hand.findIndex(c => c.id === cardId);
    if (cardIndex === -1) return false;

    const card = hand.splice(cardIndex, 1)[0];

    // 打出的牌背面朝上，加入弃牌堆
    this.gameState.discardedPile.push({
        playerId,
        card,
        hidden: true // 背面朝上
    });

    // 下一位玩家
    this.nextPlayer();

    return true;
}

