// 更新牌墙状态
updateWallState() {
    // 计算已抓取的牌数
    const initialCards = 136 - 1; // 总牌数减去亮牌
    const remainingCards = this.gameState.deck.length;
    const drawnCards = initialCards - remainingCards;

    // 牌墙初始状态：每个方位17墩（34张）
    const initialPiles = { 1: 17, 2: 17, 3: 17, 4: 17 };

    // 抓牌顺序（顺时针）：根据抓牌起始位置确定
    // drawInfo.startDirection 是抓牌起始方位（1-4）
    const drawInfo = this.gameState.drawInfo;
    if (!drawInfo) {
        this.gameState.wallState = initialPiles;
        return;
    }

    const startDir = drawInfo.startDirection;
    // 顺时针顺序：东(1)→南(2)→西(3)→北(4)
    // 但实际抓牌是从起始墩的下一墩开始
    const startPile = drawInfo.drawPile || 0;

    // 计算已抓取的牌墩数（每墩2张）
    const drawnPiles = Math.floor(drawnCards / 2);
    const singleCard = drawnCards % 2; // 是否有单张

    // 从起始方位开始，顺时针分配已抓取的牌墩
    // 先计算起始方位之前要跳过的牌墩
    const directionOrder = [1, 2, 3, 4]; // 顺时针：东南西北
    const startIdx = directionOrder.indexOf(startDir);

    // 起始方位之前已抓取的牌墩数（从起始墩开始抓）
    // 起始方位剩余的牌墩 = 17 - startPile
    let wallState = { 1: 17, 2: 17, 3: 17, 4: 17 };

    // 标记起始方位已抓取的牌墩
    wallState[startDir] = startPile;

    // 剩余需要抓取的牌墩
    let remainingPilesToDraw = drawnPiles;
    if (wallState[startDir] < 17) {
        // 起始方位已抓了一些
    }

    // 按顺时针方向减少牌墩
    let currentDirIdx = startIdx;
    while (remainingPilesToDraw > 0) {
        const available = wallState[directionOrder[currentDirIdx]];
        if (remainingPilesToDraw >= available) {
            wallState[directionOrder[currentDirIdx]] = 0;
            remainingPilesToDraw -= available;
        } else {
            wallState[directionOrder[currentDirIdx]] -= remainingPilesToDraw;
            remainingPilesToDraw = 0;
        }
        currentDirIdx = (currentDirIdx + 1) % 4;
    }

    this.gameState.wallState = wallState;
}

