        tile1.className = 'wall-tile top-tile';
        const tile2 = document.createElement('div');
        tile2.className = 'wall-tile bottom-tile';

        // 检查是否是亮牌位置
        if (shownInfo && shownInfo.direction === seatNum && shownInfo.pile === (17 - i)) {
            tile1.classList.add('shown');
            // 在亮牌位置显示麻将牌图片
            if (currentShownCard) {
                const imgSrc = getCardImageSrc(currentShownCard);
                if (imgSrc) {
                    // 创建图片元素显示在牌墙上
                    const img = document.createElement('img');
                    img.src = imgSrc;

                    // 根据方位调整图片旋转和尺寸
                    // 方位映射: North=3(上), South=1(下), West=4(左), East=2(右)
                    let rotation = 0;
                    let imgWidth = '100%';
                    let imgHeight = '100%';

                    if (dir === 'North') {
                        // 上方牌墙（北）- 图片正向
                        rotation = 0;
                    } else if (dir === 'South') {
                        // 下方牌墙（南）- 图片旋转180度
                        rotation = 180;
                    } else if (dir === 'West') {
                        // 左方牌墙（西）- 图片逆时针旋转90度
                        rotation = -90;
                        imgWidth = '100%';
                        imgHeight = 'auto';
                    } else if (dir === 'East') {
                        // 右方牌墙（东）- 图片顺时针旋转90度
                        rotation = 90;
                        imgWidth = '100%';
                        imgHeight = 'auto';
                    }

                    img.style.cssText = `width:${imgWidth};height:${imgHeight};object-fit:cover;border-radius:2px;transform:rotate(${rotation}deg);`;
                    tile1.innerHTML = '';
                    tile1.appendChild(img);
                }
            }
        }

        pile.appendChild(tile1);
        pile.appendChild(tile2);
    } else {
        // 已被抓走的牌墩
        const emptyTile = document.createElement('div');
        emptyTile.className = 'wall-tile empty';
        pile.appendChild(emptyTile);
    }

    wallEl.appendChild(pile);
}

